"use strict";(self.webpackChunkapp=self.webpackChunkapp||[]).push([[5258],{5258:(b,m,c)=>{c.d(m,{Q8:()=>p,WA:()=>l,dk:()=>u});const e=4e3,a=7e3,o=1e4,u=[{id:1,interval:e,dusker:!0,img:"/assets/sprites/vampire.jpg",name:"Vampiro (Vampire)",slug:"vampire",originalOrder:"-6",description:"Vampiros (incluindo o Mestre[The Master] e o Conde [The Count]) acorda e procura por outros vampiros.Ent\xe3o eles escolhem outro jogador n\xe3o vampiro para colocar a marca do vampiro, trocando a marca original sem olhar e colocando ela no espa\xe7o da marca vazia do vampiro.<br> <br><span> O Vampiro faz parte do time dos Vampiros.</span>"},{id:2,interval:e,dusker:!0,img:"/assets/sprites/the-count.jpg",name:"O Conde (The Count)",slug:"count",originalOrder:"-6b",description:"O Conde(The Count) acorda junto dos vampiros e procura por outros vampiros. Ele acorda depois que os outros vampiros fecham os olhos e deve colocar a <strong>marca de medo </strong> na frente de outro jogador n\xe3o vampiro (ele pode n\xe3o pode colocar no jogador que recebeu a marca do vampiro, pois ele agora faz parte do time dos vampiros). O jogador que recebeu a marca de medo n\xe3o pode realizar a a\xe7\xe3o durante a noite (se ele tiver a\xe7\xe3o). <br><br> <span> O Conde faz parte do time dos Vampiros.</span>"},{id:4,interval:0,dusker:!0,img:"/assets/sprites/the-master.jpg",name:"O mestre (The Master)",slug:"master",originalOrder:"",description:"O Mestre (The Master) acorda junto dos vampiros e procura por outros vampiros. O poder especial do Mestre s\xf3 funciona durante a vota\xe7\xe3o:  <br> Se outro Vampiro (o vampiro comum, o vampiro, o conde) votar nele, o mestre est\xe1 protegido e n\xe3o pode ser eliminado. Em vez disso, o jogador com o segundo maior n\xfamero de votos (maior que 1) \xe9 eliminado. <br><br><span> O Mestre faz parte do time dos Vampiros.</span>"},{id:3,interval:e,dusker:!0,img:"/assets/sprites/renfield.jpg",name:"Renfield",slug:"renfield",originalOrder:"-6c",description:"O Conde n\xe3o acorda durante a noite. Se o Conde for eliminado, ele escolhe um jogador para se tornar o novo Conde. O jogador escolhido n\xe3o revela sua nova identidade at\xe9 o final do jogo. <br> <br><span> O Renfield faz parte do time dos Vampiros.</span>"},{id:4,interval:a,dusker:!0,img:"/assets/sprites/diseased.jpg",name:"Diseased",slug:"diseased",originalOrder:"-5",description:"A doente (Diseased) acorda e deve colocar a marca do doente (mark of disease) em um jogador ao lado esquerdo ou direito dela e colocar a marca original do jogador que ela escolheu (sem olhar) virado pra baixo no local da marca que ela tirou. <br>Qualquer jogador que votar no jogador <strong>Doente</strong> n\xe3o pode ganhar, mesmo se o time dele for o vencedor. Porem, o voto ainda \xe9 contabilizado, e se o jogador com a carta de <strong>Doente</strong> ou a marca da doen\xe7a for quem recebeu mais votos, ele \xe9 eliminado como qualquer outro jogador, e apenas os jogadores do time vencedor que n\xe3o votaram no <strong> Doente</strong> s\xe3o os jogadores vencedores.<br><br> <span> O Doente faz parte do time da Vila.</span>"},{id:4,interval:a,dusker:!0,img:"/assets/sprites/diseased.jpg",name:"Doente",slug:"doente",originalOrder:"-5",description:"A doente (Diseased) acorda e deve colocar a marca do doente (mark of disease) em um jogador ao lado esquerdo ou direito dela e colocar a marca original do jogador que ela escolheu (sem olhar) virado pra baixo no local da marca que ela tirou. <br>Qualquer jogador que votar no jogador <strong>Doente</strong> n\xe3o pode ganhar, mesmo se o time dele for o vencedor. Porem, o voto ainda \xe9 contabilizado, e se o jogador com a carta de <strong>Doente</strong> ou a marca da doen\xe7a for quem recebeu mais votos, ele \xe9 eliminado como qualquer outro jogador, e apenas os jogadores do time vencedor que n\xe3o votaram no <strong> Doente</strong> s\xe3o os jogadores vencedores.<br><br> <span> O Doente faz parte do time da Vila.</span>"},{id:5,interval:a,dusker:!0,img:"/assets/sprites/cupid.jpg",name:"Cupido",slug:"cupid",originalOrder:"-4",description:"O c\xfapido (Cupid) acorda e coloca a marca de amor na frente de dois outros jogadores, ela deve colocar as marcas originais no local vazio das marcas do amor. <br>Jogadores que receberam a marca do amor acordam juntos ap\xf3s a fase do crepusculo(dusk) terminar e est\xe3o enamorados. Se um dos dois jogadores for eliminado o outro tamb\xe9m \xe9 eliminado junto. Jogadores com a marca do amor continuam no mesmo time a que a carta deles pertece. <br><br> <span> O C\xfapido faz parte do time da Vila.</span>"},{id:6,interval:a,dusker:!0,img:"/assets/sprites/instigator.jpg",name:"Instigador",slug:"instigator",originalOrder:"-3",description:"O instigador acorda e coloca a marca de traidor virado para baixo na frente de outro jogador e coloca a marca original (sem olhar) no local vazio no tabuleiro. <br>O jogador que recebeu a marca do traidor (mark of the traitor) somente vence se alguem do time dele for eliminado. Se o jogador com a marca do traidor \xe9 a unica pessoa no time dele, a marca do traidor n\xe3o tem efeito. <br><br> <span> O Instigador faz parte do time da Vila.</span>"},{id:5,interval:a,dusker:!0,img:"/assets/sprites/priest.jpg",name:"Sacerdote",slug:"priest",originalOrder:"-2",description:"O Sacerdote (Priest) acorda e deve colocar uma marca de clareza em si proprio e em outro jogador, devolvendo as marcas originais de cada jogador para os espa\xe7os vazios do tabuleiro. <br><br> <span> O Sacerdote faz parte do time da Vila.</span>"},{id:6,interval:a,dusker:!0,img:"/assets/sprites/assassin.jpg",name:"Assassino",slug:"assassin",originalOrder:"-1",description:"O assassino acorda e deve colocar a marca do assassino em outro jogador e devolver a marca original do jogador para o espa\xe7o vazio no tabuleiro. <br> O assassino s\xf3 consegue vencer apenas se o jogador com a marca do assassino for eliminado, independente de qual time o jogador perten\xe7a. O assassino n\xe3o precisa sobreviver ao final do jogo para vencer.  <br> O assassino \xe9 o unico que se ele vencer, os outros times tamb\xe9m podem vencer, ent\xe3o \xe9 possivel do assassino vencer junto dos vampiros, vila ou o suicida(tanner).<br>Se acontecer do proprio assassino acabar com a marca do assassino no final do jogo, ele somente vence se ele pr\xf3prio for eliminado. <br> <br><span> O assassino pertence apenas ao pr\xf3prio time.</span>"},{id:7,interval:a,dusker:!0,img:"/assets/sprites/apprentice-assassin.jpg",name:"Assassino Aprendiz",slug:"apprentice-assassin",originalOrder:"-1B",description:"O Aprendiz de Assassino acorda imediatamente depois do assassino colocar a marca do assassino em outro jogador, enquanto o assassino esta com os olhos abertos. O aprendiz de asssino e o assassino se reconhecem. <br>O aprendiz de assassino vence se o assassino for eliminado. O aprendiz de asssino n\xe3o precisa esta vivo no final do jogo para ganhar.  <br> Se n\xe3o tiver um assasino no jogo, o aprendiz de asssino deve colocar a marca na frente de outro jogador e somente vence se o jogador com a marca for eliminado, incluido ele mesmo.  <br><br><span> O aprendiz de assassino pertence apenas ao pr\xf3prio time.</span>"},{id:8,interval:e,dusker:!1,img:"/assets/sprites/lovers.jpg",name:"Amantes",slug:"lovers",originalOrder:"0",description:"Assim que iniciar a noite, os jogadores que est\xe3o enamorados ( os que possuem a marca do amor) acordam e se reconhecem um ao outro. Os jogadores com a marca de amor esta ligados, se um eliminado o outro jogador \xe9 eliminado tamb\xe9m. <br> \xc9 possivel que somente um jogador possua a marca do amor se o instigador, sacerdote, assassino ou aprendiz de assassino estiverem no jogo. Se for esse o caso, a marca do amor n\xe3o tem nenhum efeito. <br> <span> Possuir a marca do amor n\xe3o troca o time a qual a carta do jogador pertence.</span>"},{id:9,interval:o,dusker:!1,img:"/assets/sprites/marksman.jpg",name:"Marksman",slug:"marksman",originalOrder:"5D",description:"Marksman O <strong>Marksman</strong> acorda e pode olhar uma carta de jogador e a marca de outro jogador (n\xe3o pode olhar a marca e carta do mesmo jogador). <br> <br> <span> O Marksman faz parte do time da Vila.</span>"},{id:10,interval:a,dusker:!1,img:"/assets/sprites/pickpocket.jpg",name:"Pickpocket",slug:"pickpocket",originalOrder:"6C",description:"O Pickpocket acorda e pode trocar a marca dele com a marca de outro jogador e ent\xe3o ve sua nova marca. <br> <br> <span> O Pickpocket faz parte do time da vila.</span>"},{id:11,interval:a,dusker:!1,img:"/assets/sprites/gremlin.jpg",name:"Gremlin",slug:"gremlin",originalOrder:"7D",description:"O <strong>Gremlin</strong> acorda durante a noite e pode troca a carta ou a marca (n\xe3o os dois) entre outros dois jogadores, mas sem olhar a marca ou a carta que foi trocada. <br><br><span> O Gremlin faz parte do time da Vila.</span>"}],l=[{id:0,interval:a,dusker:!1,img:"/assets/sprites/sentinela.jpg",name:"Sentinela",slug:"sentinela",originalOrder:"0A",description:"O Sentinela acorda e pode colocar uma ficha de escudo sobre a carta de qualquer jogador, exceto a sua pr\xf3pria.Essa carta n\xe3o pode ser vista nem movida, e n\xe3o pode receber uma ficha de Artefato. A ficha de escudo impede que os seguintes pap\xe9is vejam ou movam sua pr\xf3pria carta, caso ela esteja protegida: <ul>    <li>Bruxa (Witch)</li>    <li>Ladr\xe3o (Robber)</li>    <li>B\xeabado (Drunk)</li>    <li>Son\xe2mbula (Insomniac)</li> </ul> Embora o poder do B\xeabado normalmente seja obrigat\xf3rio, uma ficha de escudo na sua carta impede que ele use seu poder.Durante a prepara\xe7\xe3o do jogo, uma ficha de escudo deve ser colocada pr\xf3xima \xe0s cartas do centro, para que o Sentinela possa peg\xe1-la facilmente.<br> <span>O Sentinela faz parte da equipe da vila.</span>"},{id:1,interval:a,dusker:!1,img:"/assets/sprites/lobisomem.jpg",name:"Lobisomem",slug:"lobisomens",originalOrder:"2",description:"A noite, todos os lobisomens acordam e se reconhecem. Se ninguem abrir os olhos, os outros lobisomens est\xe3o no centro da mesa. <br> Op\xe7\xe3o de Lobo Solit\xe1rio: Se houver apenas um lobisomem no jogo, o Lobisomem pode olhar uma carta no centro. Isto \xe9 extremamente ben\xe9fico para o Lobisomem, que n\xe3o tem um parceiro e fornece uma ferramenta util para enganar os outros jogadores."},{id:2,interval:a,dusker:!1,img:"/assets/sprites/alpha.jpg",name:"Lobisomem Alpha",slug:"lobisomem-alpha",originalOrder:"2B",description:"Se estiver jogando com o Lobo Alfa, posicione qualquer outra carta de Lobisomem (incluindo um Lobisomem comum, o Lobisomem M\xedstico ou o Lobisomem Sonhador) virada para baixo e perpendicular \xe0s tr\xeas cartas centrais (veja a imagem abaixo para um exemplo de onde colocar a carta de Lobisomem Central). <img src='/assets/setup.jpg' alt='Lobo Alfa Setup' style='max-width: 100%; margin-top: 10px;'/><br>Durante a noite, o Lobo Alfa acorda junto com os outros Lobisomens. Depois disso, o Lobo Alfa acorda separadamente. O Lobo Alfa deve trocar a carta de Lobisomem Central com a carta de qualquer outro jogador (mas n\xe3o pode trocar com a pr\xf3pria carta nem com a carta de outro Lobisomem), sem olhar para nenhuma das duas cartas. Todos os pap\xe9is que podem ver ou mover uma carta central tamb\xe9m podem ver ou mover a carta de Lobisomem Central.<br> <span>O Lobo Alfa faz parte da equipe dos Lobisomens.</span>"},{id:3,interval:a,dusker:!1,img:"/assets/sprites/mystic.jpg",name:"Lobisomem M\xedstico",slug:"lobisomem-mistico",originalOrder:"2C",description:"O Lobisomem M\xedstico acorda junto com os outros Lobisomens. Depois disso, o Lobisomem M\xedstico acorda separadamente. O Lobisomem M\xedstico pode olhar a carta de outro jogador. <br> <span>O Lobisomem M\xedstico faz parte da equipe dos Lobisomens.</span>"},{id:4,interval:e,dusker:!1,img:"/assets/sprites/minion.jpg",name:"Minion",slug:"minion",originalOrder:"3",description:" Age logo ap\xf3s a a\xe7\xe3o dos Lobisomens. o Minion acorda e ve quem s\xe3o os Lobisomens, Durante esta fase, todos os Lobisomens colocam seus ded\xf5es para cima para que o Minion  possa ver quem s\xe3o. Os Lobisomens n\xe3o sabem quem \xe9 o Minion. Se o Minion for eliminado e nenhum Lobisomem for eliminado, os Lobisomens (e o Minion) vencem. Se nenhum jogador for Lobisomem, o Minion vence se qualquer outro jogador for eliminado (que n\xe3o seja Minion). Esta fun\xe7\xe3o pode ser um aliado muito poderoso para o time dos Lobisomens."},{id:5,interval:e,dusker:!1,img:"/assets/sprites/mason.jpg",name:"Mason",slug:"ma\xe7ons",originalOrder:"4",description:"A Quando estiver usando os Ma\xe7ons, coloque os dois no jogo. O Ma\xe7om acorda durante a noite e procura o outro Ma\xe7om. Se o Ma\xe7om n\xe3o encontrar outro Ma\xe7om, ele sabe que o outro est\xe1 no centro da mesa. <br> <span> Os Ma\xe7ons est\xe1 no time do vilarejo.</span>"},{id:6,interval:a,dusker:!1,img:"/assets/sprites/vidente.jpg",name:"Vidente",slug:"vidente",originalOrder:"5",description:"A noite, o Vidente acorda e pode olhar a carta de outro jogador ou duas cartas do centro da mesa, mas n\xe3o pode move-las. <span> A Vidente est\xe1 no time do vilarejo.</span>"},{id:7,interval:a,dusker:!1,img:"/assets/sprites/aprendiz-vidente.jpg",name:"Aprendiz de Vidente",slug:"aprendiz-de-vidente",originalOrder:"5B",description:"A Vidente Aprendiz acorda e pode olhar uma das cartas do centro. <br> <span>A Vidente Aprendiz faz parte da equipe da vila.</span>"},{id:8,interval:o,dusker:!1,img:"/assets/sprites/investigador.jpg",name:"Investigador Paranormal",slug:"investigador-paranormal",originalOrder:"5C",description:"O Investigador Paranormal acorda e pode olhar as cartas de at\xe9 dois outros jogadores, uma de cada vez. Se ele vir um Lobisomem ou um Suicida (Tanner), n\xe3o pode mais olhar outras cartas e se torna um Lobisomem ou Suicida, respectivamente.Se o Investigador Paranormal ver o Doppelg\xe4nger que viu um Lobisomem, ele continua olhando normalmente, pois n\xe3o sabe o que o Doppelg\xe4nger viu e n\xe3o se torna o mesmo papel, mesmo que o Doppelg\xe4nger tenha se tornado um Lobisomem ou Suicida. <br> O Investigador Paranormal faz parte da equipe da vila, a menos que encontre um Lobisomem, nesse caso, ele se junta \xe0 equipe dos Lobisomens, ou se encontrar um Suicida, torna-se um Suicida e s\xf3 vence se for eliminado."},{id:9,interval:a,dusker:!1,img:"/assets/sprites/ladrao.jpg",name:"Ladr\xe3o",slug:"ladrao",originalOrder:"6",description:"A noite, o Ladr\xe3o acorda e pode roubar uma carta de outro jogador e colocar sua carta no lugar da outra carta. Ent\xe3o o Ladr\xe3o pode olhar sua nova carta. O jogador que recebe a carta do Ladr\xe3o est\xe1 no time da vila. O Ladr\xe3o fica no time da carta que ele pegou, no entanto, ele n\xe3o faz a a\xe7\xe3o da nova carta durante a noite.<br>Se o Ladr\xe3o escolher n\xe3o roubar a carta do outro jogador, ele permanece como Ladr\xe3o. <br> <span> O Ladr\xe3o est\xe1 no time do vilarejo.</span>"},{id:10,interval:a,dusker:!1,img:"/assets/sprites/bruxa.jpg",name:"Bruxa",slug:"bruxa",originalOrder:"6B",description:"A Bruxa acorda e pode olhar uma das cartas do centro.Se ela olhar uma carta do centro, deve troc\xe1-la com a carta de qualquer jogador (inclusive a pr\xf3pria). A carta do jogador trocado deve ser colocada de volta no centro, no mesmo lugar, sem olhar para ela. A Bruxa faz parte da <strong>equipe da vila</strong>, a menos que troque sua pr\xf3pria carta por uma de outra equipe."},{id:11,interval:o,dusker:!1,img:"/assets/sprites/encrenqueira.jpg",name:"Encrenqueira",slug:"encrenqueira",originalOrder:"7",description:"A noite, a Encrenqueira acorda e pode trocar as cartas de dois outros jogadores sem olhar as cartas. Os jogadores que recebem as cartas diferentes s\xe3o agora do time da carta que eles receberam, mesmo que eles n\xe3o saibam e essa fun\xe7\xe3o permanece ate o final do jogo. <br><span> O encrenqueiro esta no time do vilarejo.</span>"},{id:12,interval:o,dusker:!1,img:"/assets/sprites/idiota-vila.jpg",name:"Idiota da Vila",slug:"idiota-da-vila",originalOrder:"7B",description:"O Idiota da Vila acorda e pode mover as cartas de todos os jogadores, exceto a sua pr\xf3pria, uma posi\xe7\xe3o para a esquerda ou para a direita. Se ele decidir mover as cartas, deve mover todas as cartas dos jogadores (exceto a dele), n\xe3o pode mover cartas do centro, nem cartas com ficha de escudo. <br> <span>O Idiota da Vila faz parte da equipe da vila.</span>"},{id:13,interval:a,dusker:!1,img:"/assets/sprites/bebado.jpg",name:"B\xeabado",slug:"bebado",originalOrder:"8",description:"O B\xeabado est\xe1 t\xe3o b\xeabado que n\xe3o se lembra da sua fun\xe7\xe3o. Quando for a hora de acordar durante a noite, ele deve trocar sua carta de B\xeabado por qualquer carta do centro, mas ele n\xe3o olha a sua carta. O B\xeabado assume a fun\xe7\xe3o da carta sua frente (mesmo que ele n\xe3o saiba que fun\xe7\xe3o \xe9 essa) e est\xe1 no time dessa fun\xe7\xe3o."},{id:14,interval:e,dusker:!1,img:"/assets/sprites/sonambula.jpg",name:"Son\xe2mbula",slug:"sonambula",originalOrder:"9",description:" A Son\xe2mbula acorda e procura pela sua carta (pra ver se ela mudou). Apenas use a Son\xe2mbulase o ladr\xe3o ou encrenqueira estiverem no jogo. <span> A Son\xe2mbula est\xe1 no time do vilarejo.</span>"},{id:15,interval:o,dusker:!1,img:"/assets/sprites/revelador.jpg",slug:"revelador",name:"Revelador",originalOrder:"10",description:"O Revelador acorda e pode virar a carta de outro jogador para cima.Se a carta revelada for um Lobisomem ou um Enforcado (Tanner), ele deve vir\xe1-la novamente para baixo.Se o Revelador revelar uma carta de Doppelg\xe4nger ou Investigador Paranormal (P.I.), ele a deixa virada para cima.O Revelador s\xf3 pode virar uma carta para cima, mesmo que revele um Lobisomem ou Enforcado.<br> <span>O Revelador faz parte da equipe da vila.</span>"},{id:16,interval:a,dusker:!1,img:"/assets/sprites/curador.jpg",name:"Curador",slug:"curador",originalOrder:"11",description:"O Curador acorda e pode escolher e colocar uma ficha de Artefato virada para baixo, aleatoriamente (sem olhar) sobre a carta de qualquer jogador (inclusive a sua pr\xf3pria). Consulte a lista de artefatos para ver os efeitos de cada um. O Curador n\xe3o pode colocar uma ficha de Artefato em uma carta que tenha uma ficha de escudo. <br> <span>O Curador faz parte da equipe da vila.</span>"},{id:17,interval:0,dusker:!1,img:"/assets/sprites/ca\xe7ador.jpg",name:"Ca\xe7ador",slug:"ca\xe7ador",originalOrder:"999",description:"O Ca\xe7ador n\xe3o acorda durante a noite. Se o Ca\xe7ador for eliminado,o outro jogador que ele estiver apontando \xe9 eliminado tamb\xe9m.<br> <span> O Ca\xe7ador est\xe1 no time do vilarejo.</span>"},{id:18,interval:0,dusker:!1,img:"/assets/sprites/suicida.jpg",name:"Suicida",slug:"suicida",originalOrder:"999",description:"<p> O Suicida odeia tanto seu trabalho que ele quer morrer.</p><ul><li>Se o Suicida for eliminado, ele vence sozinho.</li><li>Se o Suicida for eliminado e nenhum Lobisomem for eliminado, os Lobisomens n\xe3o vencem.</li><li>Se o Suicida for eliminado e um Lobisomem tamb\xe9m, o time da Vila tamb\xe9m vence.</li><li>O Suicida \xe9 considerado membro da Vila (mas ele n\xe3o esta no time deles), portanto seo Suicida for eliminado, e todos os Lobisomens estiverem no centro, o time da Vila perde</li></ul>"},{id:19,interval:0,dusker:!1,img:"/assets/sprites/dreamwolf.jpg",slug:"lobisomem-dos-sonhos",name:"Lobisomem Sonhador",originalOrder:"999",description:"O Lobisomem Sonhador n\xe3o acorda com os outros Lobisomens.Quando os Lobisomens s\xe3o chamados \xe0 noite, ele apenas levanta o polegar, para que os outros Lobisomens saibam quem ele \xe9. Se estiver jogando com o Capanga (Minion), o Lobisomem Sonhador tamb\xe9m levanta o polegar durante a fase noturna do Capanga. <br> <span>O Lobisomem Sonhador faz parte da equipe dos Lobisomens.</span>"}];function p(i,n){const r=/^(-?\d+)([a-z]*)$/i,[,d,g]=i.match(r)||[],[,t,v]=n.match(r)||[];return+d!=+t?+d-+t:g.localeCompare(v)}}}]);